#include <bits/stdc++.h>
using namespace std;

static char buf[1 << 25];

int main() {
    size_t len = fread(buf, 1, sizeof(buf) - 1, stdin);
    buf[len] = 0;
    char *p = buf;
    auto skip = [&]() { while (*p && isspace((unsigned char)*p)) p++; };
    auto readInt = [&]() { skip(); int v = 0; while (*p >= '0' && *p <= '9') v = v * 10 + (*p++ - '0'); return v; };
    int n = readInt(), q = readInt();
    skip();
    string chars(p, n);
    p += n;
    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; i++) {
        int u = readInt() - 1, v = readInt() - 1;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    for (auto &adj : g) sort(adj.begin(), adj.end());

    // Iterative post-order (children by increasing id): each subtree is a contiguous range [start, end).
    vector<int> start(n), end(n);
    string s;
    s.reserve(n);
    vector<tuple<int, int, bool>> stack{{0, -1, false}};
    while (!stack.empty()) {
        auto [u, par, leaving] = stack.back();
        stack.pop_back();
        if (leaving) { s += chars[u]; end[u] = s.size(); continue; }
        start[u] = s.size();
        stack.push_back({u, par, true});
        for (int i = (int)g[u].size() - 1; i >= 0; i--)
            if (g[u][i] != par) stack.push_back({g[u][i], u, false});
    }

    // Manacher: odd[i] = radius of the longest odd palindrome centred at i,
    // even[i] = half-length of the longest even palindrome centred between i-1 and i.
    vector<int> odd(n), even(n);
    for (int i = 0, l = 0, r = -1; i < n; i++) {
        int k = i > r ? 1 : min(odd[l + r - i], r - i + 1);
        while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) k++;
        odd[i] = k;
        if (i + k - 1 > r) l = i - k + 1, r = i + k - 1;
    }
    for (int i = 0, l = 0, r = -1; i < n; i++) {
        int k = i > r ? 0 : min(even[l + r - i + 1], r - i + 1);
        while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k]) k++;
        even[i] = k;
        if (i + k - 1 > r) l = i - k, r = i + k - 1;
    }

    string out;
    out.reserve(2 * q + 2);
    for (int t = 0; t < q; t++) {
        int u = readInt() - 1, a = start[u], b = end[u], length = b - a, center = (a + b) / 2;
        bool ok = length % 2 ? odd[center] >= length / 2 + 1 : even[center] >= length / 2;
        if (t) out += ' ';
        out += ok ? '1' : '0';
    }
    out += '\n';
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] data;
    static int pos;

    static void skip() { while (pos < data.length && data[pos] <= ' ') pos++; }

    static int readInt() {
        skip();
        int v = 0;
        while (pos < data.length && data[pos] >= '0' && data[pos] <= '9') v = v * 10 + (data[pos++] - '0');
        return v;
    }

    public static void main(String[] args) throws IOException {
        data = System.in.readAllBytes();
        int n = readInt(), q = readInt();
        skip();
        byte[] chars = Arrays.copyOfRange(data, pos, pos + n);
        pos += n;
        int[] eu = new int[n - 1], ev = new int[n - 1], deg = new int[n];
        for (int i = 0; i < n - 1; i++) {
            eu[i] = readInt() - 1;
            ev[i] = readInt() - 1;
            deg[eu[i]]++;
            deg[ev[i]]++;
        }
        int[] adjStart = new int[n + 1];
        for (int i = 0; i < n; i++) adjStart[i + 1] = adjStart[i] + deg[i];
        int[] adj = new int[2 * (n - 1)], fill = Arrays.copyOf(adjStart, n);
        for (int i = 0; i < n - 1; i++) { adj[fill[eu[i]]++] = ev[i]; adj[fill[ev[i]]++] = eu[i]; }
        for (int u = 0; u < n; u++) Arrays.sort(adj, adjStart[u], adjStart[u + 1]);

        // Iterative post-order (children by increasing id): each subtree is a contiguous range [start, end).
        int[] start = new int[n], end = new int[n];
        byte[] s = new byte[n];
        int sLen = 0;
        int[] stU = new int[2 * n + 1], stP = new int[2 * n + 1];
        boolean[] stLeave = new boolean[2 * n + 1];
        int top = 0;
        stU[top] = 0; stP[top] = -1; stLeave[top++] = false;
        while (top > 0) {
            top--;
            int u = stU[top], par = stP[top];
            if (stLeave[top]) { s[sLen++] = chars[u]; end[u] = sLen; continue; }
            start[u] = sLen;
            stU[top] = u; stP[top] = par; stLeave[top++] = true;
            for (int e = adjStart[u + 1] - 1; e >= adjStart[u]; e--) {
                int v = adj[e];
                if (v != par) { stU[top] = v; stP[top] = u; stLeave[top++] = false; }
            }
        }

        // Manacher: odd[i] = radius of the longest odd palindrome centred at i,
        // even[i] = half-length of the longest even palindrome centred between i-1 and i.
        int[] odd = new int[n], even = new int[n];
        for (int i = 0, l = 0, r = -1; i < n; i++) {
            int k = i > r ? 1 : Math.min(odd[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) k++;
            odd[i] = k;
            if (i + k - 1 > r) { l = i - k + 1; r = i + k - 1; }
        }
        for (int i = 0, l = 0, r = -1; i < n; i++) {
            int k = i > r ? 0 : Math.min(even[l + r - i + 1], r - i + 1);
            while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k]) k++;
            even[i] = k;
            if (i + k - 1 > r) { l = i - k; r = i + k - 1; }
        }

        StringBuilder sb = new StringBuilder(2 * q + 2);
        for (int t = 0; t < q; t++) {
            int u = readInt() - 1, a = start[u], b = end[u], length = b - a, center = (a + b) / 2;
            boolean ok = length % 2 == 1 ? odd[center] >= length / 2 + 1 : even[center] >= length / 2;
            if (t > 0) sb.append(' ');
            sb.append(ok ? '1' : '0');
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"sort"
)

func main() {
	data, _ := io.ReadAll(bufio.NewReaderSize(os.Stdin, 1<<20))
	pos := 0
	skip := func() {
		for pos < len(data) && data[pos] <= ' ' {
			pos++
		}
	}
	readInt := func() int {
		skip()
		v := 0
		for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
			v = v*10 + int(data[pos]-'0')
			pos++
		}
		return v
	}
	n, q := readInt(), readInt()
	skip()
	chars := data[pos : pos+n]
	pos += n
	g := make([][]int, n)
	for i := 0; i < n-1; i++ {
		u, v := readInt()-1, readInt()-1
		g[u] = append(g[u], v)
		g[v] = append(g[v], u)
	}
	for _, adj := range g {
		sort.Ints(adj)
	}

	// Iterative post-order (children by increasing id): each subtree is a contiguous range [start, end).
	start := make([]int, n)
	end := make([]int, n)
	s := make([]byte, 0, n)
	type frame struct {
		u, par  int
		leaving bool
	}
	stack := []frame{{0, -1, false}}
	for len(stack) > 0 {
		f := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if f.leaving {
			s = append(s, chars[f.u])
			end[f.u] = len(s)
			continue
		}
		start[f.u] = len(s)
		stack = append(stack, frame{f.u, f.par, true})
		for i := len(g[f.u]) - 1; i >= 0; i-- {
			if v := g[f.u][i]; v != f.par {
				stack = append(stack, frame{v, f.u, false})
			}
		}
	}

	// Manacher: odd[i] = radius of the longest odd palindrome centred at i,
	// even[i] = half-length of the longest even palindrome centred between i-1 and i.
	odd := make([]int, n)
	even := make([]int, n)
	for i, l, r := 0, 0, -1; i < n; i++ {
		k := 1
		if i <= r {
			k = min(odd[l+r-i], r-i+1)
		}
		for i-k >= 0 && i+k < n && s[i-k] == s[i+k] {
			k++
		}
		odd[i] = k
		if i+k-1 > r {
			l, r = i-k+1, i+k-1
		}
	}
	for i, l, r := 0, 0, -1; i < n; i++ {
		k := 0
		if i <= r {
			k = min(even[l+r-i+1], r-i+1)
		}
		for i-k-1 >= 0 && i+k < n && s[i-k-1] == s[i+k] {
			k++
		}
		even[i] = k
		if i+k-1 > r {
			l, r = i-k, i+k-1
		}
	}

	out := make([]byte, 0, 2*q+2)
	for t := 0; t < q; t++ {
		u := readInt() - 1
		a, b := start[u], end[u]
		length, center := b-a, (a+b)/2
		var ok bool
		if length%2 == 1 {
			ok = odd[center] >= length/2+1
		} else {
			ok = even[center] >= length/2
		}
		if t > 0 {
			out = append(out, ' ')
		}
		if ok {
			out = append(out, '1')
		} else {
			out = append(out, '0')
		}
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
